use rs_decimal::config::ConfigValue;
let original = Decimal::new_from_string("1.2300")?;
let input = ConfigValue::Decimal(&original);
fn clone_value<T: Clone>(input: &T) -> T { input.clone() }
let copy = clone_value(&input);
let value = serde_json::json!({"value": format!("{copy:?}") == format!("{input:?}")});
